if(type==='reports15'||type==='settings15'){const report=type==='reports15';const items=report?[['salesreport','تقرير مبيعات شامل','المبيعات حسب الفترة والخيارات المتاحة.'],['customerreport','حسب العملاء','متابعة مبيعات كل عميل.'],['salespeople','حسب مندوبي المبيعات','متابعة إنتاجية المندوبين.'],['productsreport','حسب الخدمات','مقارنة الخدمات المباعة.']]:[['newsalesperson','مندوبي المبيعات','إضافة مندوب وإدارة إعداداته.'],['quotetemplates','قوالب عروض الأسعار','القوالب والشروط المتكررة للعروض.']];box.innerHTML='<div class="m15"><div class="m15-head"><div><h2>'+(report?'تقارير المبيعات':'إعدادات المبيعات')+'</h2><p>اختر الصفحة المطلوبة؛ لا توجد قوائم مخفية.</p></div>'+(report?btn('إرسال تقرير للمدير التنفيذي','sales-exec'):'')+'</div><div class="m15-grid">'+items.map(([v,t,d])=>'<section class="m15-card"><h3>'+t+'</h3><p>'+d+'</p>'+btn('فتح','sales',v)+'</section>').join('')+'</div></div>';Q('crumb').innerHTML='<b>قسم المبيعات</b> / '+(report?'التقارير':'الإعدادات');return;}
