// Keep optional customer details folded; all original inputs stay in the DOM for saving.
function foldSalesForms(){const root=Q('salesDynamic');if(!root)return;root.querySelectorAll('.customer-form-section').forEach((box,i)=>{if(box.parentElement?.classList.contains('m15-sales-fold'))return;const title=box.querySelector(':scope > h4');if(!title)return;const d=document.createElement('details');d.className='m15-sales-fold';d.open=i<2;const summary=document.createElement('summary');summary.append(title);box.before(d);d.append(summary,box);});}
