// Targeted save feedback for catalogue forms; validation never closes an incomplete form.
[].forEach(([key,label])=>{const original=window[key];if(typeof original!=='function')return;window[key]=function(){const before=JSON.stringify(state),last=typeof lastSavedStateRaw==='string'?lastSavedStateRaw:null,store=window.save,alertFn=window.alert;let writes=0,message='';window.save=function(){const r=store.apply(this,arguments);writes++;return r;};window.alert=t=>{message=String(t||'');};try{const result=original.apply(this,arguments);if(writes)note('تم حفظ '+label+' بنجاح.');else if(message)note(message,true);return result;}catch(e){state=JSON.parse(before);if(last!==null)lastSavedStateRaw=last;if(typeof customersCatalog!=='undefined')customersCatalog=state.customers;if(typeof servicesCatalog!=='undefined')servicesCatalog=state.services;note('لم يتم حفظ '+label+'؛ بقي النموذج مفتوحًا للتصحيح. '+(e.name==='QuotaExceededError'?'مساحة التخزين ممتلئة.':e.message),true);return false;}finally{window.save=store;window.alert=alertFn;}};});

/* 3. Contract templates and independently editable titled clauses. */
const types=['دائم','مؤقت','تجربة','مستقل / فريلانس','تدريب'];
function templateState(){const x=state.hrContractTemplates15;return x&&typeof x==='object'?x:{version:0,common:[],types:{}};}
const contractRows=(c,kind)=>kind==='duty'?A(c.dutyClauses):A(c.conditionClauses);
function fromTemplate(type){const t=templateState();return [...A(t.common).map(r=>({...clone(r),source:'common'})),...A(t.types?.[type]).map(r=>({...clone(r),source:'type'}))].map(r=>({...r,id:uid('CLAUSE'),templateRowId:r.id}));}
function ensureContract(c){if(!c)return;const fresh=!A(state.employeeContracts).some(x=>x.id===c.id)&&!c.parentContractId;if(!Array.isArray(c.dutyClauses)&&!Array.isArray(c.conditionClauses)){
const legacy=!!(String(c.duties||'').trim()||String(c.terms||'').trim());c.dutyClauses=c.duties?[{id:uid('CLAUSE'),title:'المهام والمسؤوليات',body:c.duties,source:'custom'}]:[];c.conditionClauses=c.terms?[{id:uid('CLAUSE'),title:'شروط الشركة',body:c.terms,source:'custom'}]:[];
if(fresh&&!legacy){const rows=fromTemplate(c.type);c.dutyClauses=rows.filter(r=>r.kind==='duty');c.conditionClauses=rows.filter(r=>r.kind!=='duty');c.templateVersion=templateState().version;c.templateType=c.type;}}
}
function clauseRowsHtml(rows,kind,locked=false,template=false){return rows.map((r,i)=>'<section class="m15-clause" data-clause-id="'+E(r.id)+'" data-kind="'+kind+'"><div class="m15-clause-head"><strong>'+(kind==='duty'?'مهمة / مسؤولية':'شرط')+' '+(i+1)+'</strong>'+(r.source&&r.source!=='custom'?'<span class="m15-tag">من القالب</span>':'')+(!locked?btn('↑','clause-up',kind+'|'+i)+btn('↓','clause-down',kind+'|'+i)+btn('حذف','clause-remove',kind+'|'+i,'danger'):'')+'</div><label>العنوان *<input data-clause-title value="'+E(r.title)+'"'+(locked?' disabled':'')+'></label><label>النص *<textarea data-clause-body'+(locked?' disabled':'')+'>'+E(r.body)+'</textarea></label></section>').join('')||'<div class="m15-empty">لا توجد بنود هنا بعد. أضف بندًا بعنوان ونص.</div>';}
function contractFields(c,locked){ensureContract(c);return '<div class="m15" id="m15ContractClauses"><div class="m15-note">بنود العقد نسخة مستقلة. تعديل الإعدادات لا يغير عقدًا محفوظًا أو موقّعًا تلقائيًا.</div>'+(!locked?'<div class="m15-actions">'+btn('إعدادات شروط العقود','templates')+btn('تحديث بنود القالب لهذا العقد','contract-apply')+'</div>':'')+'<h3 style="margin-top:18px">المهام والمسؤوليات</h3><div id="m15Duties">'+clauseRowsHtml(contractRows(c,'duty'),'duty',locked)+'</div>'+(!locked?btn('+ إضافة مهمة بعنوان','clause-add','duty'):'')+'<h3 style="margin-top:24px">شروط العقد</h3><div id="m15Conditions">'+clauseRowsHtml(contractRows(c,'condition'),'condition',locked)+'</div>'+(!locked?btn('+ إضافة شرط بعنوان','clause-add','condition'):'')+'</div>';
}
function collectClauses(c){const root=Q('m15ContractClauses');if(!root||!c)return;['duty','condition'].forEach(kind=>{const previous=contractRows(c,kind);const rows=Array.from(root.querySelectorAll('.m15-clause[data-kind="'+kind+'"]')).map(el=>{const old=previous.find(x=>x.id===el.dataset.clauseId)||{};return {...old,id:el.dataset.clauseId||uid('CLAUSE'),kind,title:el.querySelector('[data-clause-title]').value.trim(),body:el.querySelector('[data-clause-body]').value.trim(),source:old.source||'custom'};});c[kind==='duty'?'dutyClauses':'conditionClauses']=rows;});c.duties=A(c.dutyClauses).map(r=>r.title+'\n'+r.body).join('\n\n');c.terms=A(c.conditionClauses).map(r=>r.title+'\n'+r.body).join('\n\n');}
function validateClauses(c){if([...A(c.dutyClauses),...A(c.conditionClauses)].some(r=>!String(r.title||'').trim()||!String(r.body||'').trim())){note('لكل بند عنوان ونص مطلوبان. أكملهما أو احذف البند الفارغ.',true);return false;}return true;}
function clausesDocument(c,kind){const rows=contractRows(c,kind),legacy=kind==='duty'?c.duties:c.terms;return rows.length?rows.map((r,i)=>'<section class="m15-print-clause"><h3>'+E((i+1)+'. '+r.title)+'</h3><p>'+E(r.body)+'</p></section>').join(''):'<p>'+E(legacy||'تُستكمل البنود قبل التوقيع.')+'</p>';}
function contractC(){return MoshHR14.v15Current?.();}
function contractRepaint(c){Q('m15Duties').innerHTML=clauseRowsHtml(contractRows(c,'duty'),'duty');Q('m15Conditions').innerHTML=clauseRowsHtml(contractRows(c,'condition'),'condition');}
function clauseAction(action,arg){const c=contractC();if(!c||Object.keys(c.signatures||{}).length||c.status==='archived'){note('العقد مقفل؛ أنشئ نسخة جديدة.',true);return;}collectClauses(c);const [kind,ix]=arg.split('|'),rows=contractRows(c,kind),i=Number(ix);if(action==='clause-add')rows.push({id:uid('CLAUSE'),kind,title:'',body:'',source:'custom'});if(action==='clause-remove')rows.splice(i,1);if(action==='clause-up'&&i>0)[rows[i-1],rows[i]]=[rows[i],rows[i-1]];if(action==='clause-down'&&i<rows.length-1)[rows[i+1],rows[i]]=[rows[i],rows[i+1]];contractRepaint(c);}
async function applyContractTemplate(typeChange=false){const c=contractC();if(!c||Object.keys(c.signatures||{}).length||c.status==='archived')return;collectClauses(c);const previousType=c.type,type=val('c14_type')||c.type;const templates=fromTemplate(type);if(!await ask('تحميل الشروط المشتركة وشروط «'+type+'»؟ يستبدل بنود القالب السابق بما فيها تعديلاتك عليها، ويبقي البنود التي أضفتها يدويًا. لا يتغير عقد محفوظ قبل حفظ هذه المسودة.')){if(typeChange&&Q('c14_type'))Q('c14_type').value=previousType;return;}
c.dutyClauses=[...templates.filter(r=>r.kind==='duty'),...A(c.dutyClauses).filter(r=>!r.source||r.source==='custom')];c.conditionClauses=[...templates.filter(r=>r.kind!=='duty'),...A(c.conditionClauses).filter(r=>!r.source||r.source==='custom')];c.templateVersion=templateState().version;c.templateType=type;c.type=type;contractRepaint(c);note(templates.length?'تم تحميل بنود القالب في المسودة؛ احفظ العقد لاعتمادها.':'لا توجد بنود للقالب المختار بعد. أضفها من الإعدادات.');}
let templateDraft=null,templateScope='common';
function templates(){if(!canManage()&&!(typeof hasPermission==='function'&&hasPermission('systemCustomization'))){note('إعدادات شروط العقود متاحة للإدارة والموارد البشرية.',true);return;}const c=contractC();if(c)collectClauses(c);templateDraft=clone(templateState());templateScope='common';templateRender();}
function templateRows(){return templateScope==='common'?templateDraft.common:(templateDraft.types[templateScope]||(templateDraft.types[templateScope]=[]));}
function templateCollect(){if(!Q('m15TemplateRows'))return;const rows=Array.from(Q('m15TemplateRows').querySelectorAll('.m15-template-row')).map(el=>({id:el.dataset.id,kind:el.querySelector('[data-kind]').value,title:el.querySelector('[data-title]').value.trim(),body:el.querySelector('[data-body]').value.trim()}));if(templateScope==='common')templateDraft.common=rows;else templateDraft.types[templateScope]=rows;}
