function currentStaff(){return A(state.staffProfiles).filter(p=>p.active!==false&&(typeof isStaffAssignable!=='function'||isStaffAssignable(p)));}
function recipients(n){if(Array.isArray(n.recipientSnapshots))return n.recipientSnapshots;return currentStaff().filter(p=>n.targetType==='employee'?String(p.id)===String(n.targetValue)||p.name===n.targetValue:n.targetType==='department'?p.department===n.targetValue:(!n.targetType||n.targetType==='all')).map(p=>({id:String(p.id),name:p.name,department:p.department||''}));}
function relevant(n,p){if(!n||n.active===false||n.deletedAt)return false;if(n.type==='alert'&&p&&A(p.hrNoticeArchive).some(r=>r.noticeId===n.id&&r.deletedAt))return false;if(Array.isArray(n.recipientIds))return !!p?.id&&n.recipientIds.map(String).includes(String(p.id));if(n.targetType==='employee')return !!p&&[String(p.id),p.name].includes(String(n.targetValue));if(n.targetType==='department')return !!p&&p.department===n.targetValue;return !n.targetType||n.targetType==='all';}
function visible(p){return A(state.hrAnnouncements).filter(n=>relevant(n,p)).slice().sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));}
function archiveCopy(n,p,legacy=false){p.hrNoticeArchive=A(p.hrNoticeArchive);if(p.hrNoticeArchive.some(r=>r.noticeId===n.id))return;p.hrNoticeArchive.push({id:uid('NOTICECOPY'),noticeId:n.id,employeeId:String(p.id),employeeName:p.name,departmentAtSend:p.department||'',type:n.type,title:n.title,message:n.message,sourceDepartment:n.sourceDepartment||'',createdAt:n.createdAt,createdBy:n.createdBy,originalTargetType:n.targetType,originalTargetValue:n.targetValue||'',readAt:n.readAtBy?.[p.id]||'',legacyRecipientInferred:legacy});}
function captureNotice(n,legacy=false){const targets=recipients(n);if(!n.recipientSnapshots){n.recipientSnapshots=targets;n.recipientIds=targets.map(x=>String(x.id));if(legacy)n.recipientSnapshotInferredAt=now();}if(n.type==='alert')targets.forEach(t=>{const p=A(state.staffProfiles).find(p=>String(p.id)===String(t.id));if(p)archiveCopy(n,p,legacy);});}
async function migrateLegacyNotices(){const notes=A(state.hrAnnouncements).filter(n=>n.type==='alert'&&!n.recipientSnapshots);if(!notes.length)return;await transaction(()=>notes.forEach(n=>captureNotice(n,true)),'');}
let commMode='announcements',archiveEmployee='',commQuery='',commOwner='hr';
function noticeRows(){return A(state.hrAnnouncements).filter(n=>['announcement','action'].includes(n.type)&&n.active!==false);}
function archiveRows(pid=''){return A(state.staffProfiles).filter(p=>!pid||String(p.id)===String(pid)).flatMap(p=>A(p.hrNoticeArchive).filter(r=>!r.deletedAt).map(r=>({...r,employeeName:p.name,employeeId:String(p.id)})));}
function readCount(n){const keys=A(n.readBy).map(String);return recipients(n).filter(p=>keys.includes(String(p.id))||keys.includes(p.name)).length;}
function ownOrManager(pid){return canManage()||String(profile()?.id||'')===String(pid);}
function archiveHtml(pid=''){const rows=archiveRows(pid).filter(r=>!commQuery||[r.employeeName,r.title,r.message].join(' ').includes(commQuery)).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));return table(['الموظف','عنوان التنبيه','من / التاريخ','الاطلاع',''],rows.map(r=>{const n=A(state.hrAnnouncements).find(x=>x.id===r.noticeId);const seen=!!r.readAt||A(n?.readBy).some(k=>[String(r.employeeId),r.employeeName].includes(String(k)));return '<tr><td>'+E(r.employeeName)+'</td><td><b>'+E(r.title)+'</b><small>'+E(r.originalTargetType==='all'?'نسخة من تنبيه لكل الشركة':r.originalTargetType==='department'?'نسخة من تنبيه القسم':'تنبيه فردي')+(r.legacyRecipientInferred?' · سجل قديم':'')+'</small></td><td>'+E(r.createdBy||'—')+'<small>'+E(stamp(r.createdAt))+'</small></td><td>'+ (seen?'تم الاطلاع':'لم يُفتح بعد')+'</td><td>'+btn('فتح النسخة','archive-detail',r.employeeId+'|'+r.id)+(canManage()?btn('حذف النسخة','archive-delete',r.employeeId+'|'+r.id,'danger'):'')+'</td></tr>';}).join(''),'لا توجد تنبيهات محفوظة لهذا الاختيار.');}
function renderComms(mode=commMode,owner=commOwner){commMode=mode;commOwner=owner==='admin'?'admin':'hr';if(commOwner==='admin'&&window.MoshV16)MoshV16.prepareAdminComms();else{if(!Q('hrApp')?.classList.contains('active'))goApp('hr');hrProHideLegacy();Q('hrProContent').style.display='block';}const commHost=Q(commOwner==='admin'?'m16AdminComms':'hrProContent');tabState(commOwner,'');if(!canManage()){commHost.innerHTML='<div class="m15"><h2>رسائلي</h2><p>السجلات الإدارية متاحة لمدير الموارد البشرية والإدارة فقط.</p>'+btn('التعاميم والتنبيهات الخاصة بي','inbox')+'</div>';return;}
document.querySelectorAll('#m15Comms').forEach(x=>x.remove());const ps=A(state.staffProfiles),ann=noticeRows();Q('hrProNav')?.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.m15==='communications'&&b.dataset.value===mode));const heading=mode==='archive'?'أرشيف تنبيهات الموظفين':'تعاميم';commHost.innerHTML='<div class="m15" id="m15Comms"><div class="m15-head"><div><h2>'+heading+'</h2><p>'+(mode==='archive'?'كل موظف له نسخة مستقلة من التنبيه؛ حتى عند استهداف قسم أو كل الشركة.':'التعاميم فقط في هذه القائمة. التنبيهات محفوظة في أرشيف الموظفين.')+'</p></div><div class="m15-actions">'+btn('+ تعميم جديد','compose','announcement','primary')+btn('+ تنبيه','compose','alert')+'</div></div><div class="m15-subtabs">'+btn('تعاميم','communications','announcements',mode==='announcements'?'active':'')+btn('أرشيف تنبيهات الموظفين','communications','archive',mode==='archive'?'active':'')+'</div><div class="m15-toolbar">'+input('بحث بالعنوان أو الموظف','m15NoticeSearch',commQuery)+(mode==='archive'?sel('الموظف','m15ArchiveEmployee',[['','كل الموظفين'],...ps.map(p=>[p.id,p.name])],archiveEmployee):'')+'</div><div id="m15CommRows">'+(mode==='archive'?archiveHtml(archiveEmployee):announcementTable(ann))+'</div><div class="m15-note">الاطلاع لا يعني الموافقة، والتنبيه لا ينشئ خصمًا أو إنذارًا رسميًا. نسخ التنبيهات مرتبطة بالمستهدفين وقت الإرسال، ولا تتغير تلقائيًا عند نقل الموظف لقسم آخر.</div></div>';Q('crumb').innerHTML='<b>'+ (commOwner==='admin'?'الإدارة':'الموارد البشرية')+'</b> / '+heading;}
function announcementTable(rows=noticeRows()){return table(['العنوان','المستهدف','المرسل / التاريخ','الاطلاع',''],rows.filter(r=>!commQuery||[r.title,r.message,r.createdBy].join(' ').includes(commQuery)).sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))).map(n=>'<tr><td><b>'+E(n.title)+'</b></td><td>'+E(n.targetType==='all'?'كل الشركة':n.targetName||n.targetValue)+'</td><td>'+E(n.createdBy||'—')+'<small>'+E(stamp(n.createdAt))+'</small></td><td><bdi>'+readCount(n)+' / '+recipients(n).length+'</bdi></td><td>'+btn('عرض التفاصيل','notice-detail',n.id)+btn('حذف','notice-delete',n.id,'danger')+'</td></tr>').join(''),'لم تسجل تعاميم بعد.');}
function openArchive(pid=''){commOwner='hr';if(!pid){archiveEmployee='';return renderComms('archive');}if(!ownOrManager(pid)){note('هذا السجل غير متاح لهذا الحساب.',true);return;}commQuery='';modal('أرشيف تنبيهات — '+(getStaffProfileById(pid)?.name||'الموظف'),archiveHtml(pid));}
async function noticeDetail(id,copy=null,employeeView=false){const n=copy||A(state.hrAnnouncements).find(n=>n.id===id);if(!n||n.deletedAt||(!copy&&n.active===false))return;if(!canManage()&&!relevant(A(state.hrAnnouncements).find(x=>x.id===id)||n,profile())&&! (copy&&String(copy.employeeId)===String(profile()?.id))){note('هذه الرسالة ليست موجهة لهذا الحساب.',true);return;}
if(employeeView){const master=A(state.hrAnnouncements).find(x=>x.id===id),p=profile();if(p&&master&&relevant(master,p)){await transaction(()=>{master.readBy=A(master.readBy);if(!master.readBy.includes(String(p.id)))master.readBy.push(String(p.id));master.readAtBy=master.readAtBy||{};master.readAtBy[p.id]=now();const r=A(p.hrNoticeArchive).find(x=>x.noticeId===id);if(r)r.readAt=master.readAtBy[p.id];},'');refreshEmployeeDailyHub();}}
const nMaster=A(state.hrAnnouncements).find(x=>x.id===id)||n;modal(n.title||'رسالة','<div class="m15-note">'+E(n.type==='alert'?'تنبيه إداري':'تعميم')+' · '+E(n.sourceDepartment||'الإدارة')+'</div><p style="white-space:pre-wrap;color:#e2e6e7">'+E(n.message)+'</p><p>'+E(n.createdBy||'—')+' · '+E(stamp(n.createdAt))+'</p>'+(copy?'<p>نسخة محفوظة في أرشيف '+E(copy.employeeName)+'.</p>':'')+(canManage()&&!employeeView?'<h3>المستهدفون وقت الإرسال</h3>'+table(['الموظف','القسم وقت الإرسال','الاطلاع'],recipients(nMaster).map(p=>'<tr><td>'+E(p.name)+'</td><td>'+E(p.department)+'</td><td>'+(A(nMaster.readBy).some(k=>[String(p.id),p.name].includes(String(k)))?'فتح الرسالة':'لم يفتحها بعد')+'</td></tr>').join('')):'')+(copy?.legacyRecipientInferred?'<div class="m15-note">هذا تنبيه قديم. رُبط السجل بالمستهدفين المطابقين وقت التحديث لعدم وجود قائمة مستلمين تاريخية في النسخة السابقة.</div>':''));if(canManage()&&!employeeView){Q('m15Modal')?.querySelector('footer')?.insertAdjacentHTML('afterbegin',(copy?btn('حذف نسخة الموظف','archive-delete',copy.employeeId+'|'+copy.id,'danger'):'')+btn(copy?'سحب التنبيه من الجميع':'حذف التعميم','notice-delete',id,'danger'));}}
function inbox(filter=''){const p=profile(),rows=visible(p).filter(n=>!filter||n.type===filter),key=String(p?.id||currentUser?.username||'');modal('التعاميم والتنبيهات',rows.map(n=>'<section class="m15-card"><div class="m15-head"><h3>'+E(n.title)+'</h3><span class="m15-tag">'+(A(n.readBy).includes(key)?'مقروءة':'جديدة')+'</span></div><p>'+E(n.type==='alert'?'تنبيه إداري خاص بك':'تعميم')+' · '+E(n.createdBy||'—')+' · '+E(stamp(n.createdAt))+'</p>'+btn('فتح الرسالة','notice-read',n.id)+'</section>').join('')||'<div class="m15-empty">لا توجد رسائل موجهة لحسابك.</div>');}
const oldComposer=window.openHrNoticeComposer;
window.openHrNoticeComposer=function(mode='announcement'){const r=oldComposer.apply(this,arguments);const s=Q('hrNoticeTargetType');if(s&&mode==='alert'){s.disabled=false;s.innerHTML='<option value="employee">موظف محدد</option><option value="department">قسم محدد — نسخة لكل موظف</option><option value="all">كل الشركة — نسخة لكل موظف</option>';s.value='employee';hrNoticeTargetChanged();const h=Q('hrProModalRoot')?.querySelector('h3');if(h)h.textContent='إرسال تنبيه وحفظ نسخة بأرشيف المستهدفين';}return r;};
let noticeBusy=false;
window.sendHrNotice=async function(){if(noticeBusy||!Q('hrNoticeMode')||!canManage())return;const type=val('hrNoticeMode'),targetType=val('hrNoticeTargetType'),targetValue=targetType==='all'?'':val('hrNoticeTargetValue'),title=val('hrNoticeTitle'),message=val('hrNoticeMessage');const fail=t=>{const e=Q('hrNoticeError');if(e){e.hidden=false;e.textContent=t;}else note(t,true);};if(!['announcement','alert'].includes(type)||!['all','department','employee'].includes(targetType)||!title||!message||targetType!=='all'&&!targetValue){fail('أكمل العنوان والنص والمستهدف الصحيح.');return;}const n={id:uid('ANN'),type,title,message,targetType,targetValue,targetName:targetType==='employee'?getStaffProfileById(targetValue)?.name||targetValue:targetValue,sourceDepartment:commOwner==='admin'?'الإدارة':'الموارد البشرية',createdAt:now(),createdBy:me(),createdById:String(profile()?.id||currentUser?.id||''),active:true,readBy:[]};const ps=recipients(n);if(!ps.length){fail('لا يوجد موظفون نشطون ضمن هذا الاختيار.');return;}noticeBusy=true;const b=Q('hrNoticeSendBtn');b.disabled=true;try{if(ps.length>1&&!await ask('إرسال '+(type==='alert'?'التنبيه وحفظ نسخة في أرشيف كل موظف':'التعميم')+' إلى '+ps.length+' موظفًا؟'))return;
const ok=await transaction(()=>{state.hrAnnouncements=A(state.hrAnnouncements);captureNotice(n);state.hrAnnouncements.push(n);},'تم حفظ '+(type==='alert'?'التنبيه ونسخ الأرشيف لـ '+ps.length+' موظفًا.':'التعميم.'));if(ok){hrProCloseModal();refreshEmployeeDailyHub();renderComms(type==='alert'?'archive':'announcements');}}
finally{noticeBusy=false;if(b.isConnected)b.disabled=false;}};
