async function deleteNotice(id){if(!canManage())return;const n=A(state.hrAnnouncements).find(x=>x.id===id);if(!n)return;if(!await ask('حذف هذه الرسالة من القوائم ومن صناديق كل المستهدفين؟ يبقى أثر الحذف في السجل الداخلي.'))return;const ok=await transaction(()=>{const record=A(state.hrAnnouncements).find(x=>x.id===id);if(!record)throw Error('الرسالة غير موجودة');record.active=false;record.deletedAt=now();record.deletedBy=me();A(state.staffProfiles).forEach(p=>A(p.hrNoticeArchive).filter(r=>r.noticeId===id).forEach(r=>{r.deletedAt=record.deletedAt;r.deletedBy=me();}));},'تم حذف الرسالة من القوائم.');if(ok){closeModal();renderComms();refreshEmployeeDailyHub();MoshEmployeeView11.refresh();}}
async function deleteCopy(arg){if(!canManage())return;const [pid,id]=arg.split('|');if(!await ask('حذف نسخة التنبيه من سجل هذا الموظف وصندوقه فقط؟ لن تُحذف نسخ زملائه.'))return;const ok=await transaction(()=>{const r=A(getStaffProfileById(pid)?.hrNoticeArchive).find(x=>x.id===id);if(!r)throw Error('نسخة التنبيه غير موجودة');r.deletedAt=now();r.deletedBy=me();},'تم حذف نسخة الموظف.');if(ok){closeModal();renderComms('archive');refreshEmployeeDailyHub();MoshEmployeeView11.refresh();}}
