let recruitMode='candidates',candidateFilter={job:'',stage:'',q:'',day:''},candidateContext=null;
const stages=[['screening','فرز أولي'],['interview','مقابلة محددة'],['accepted','مقبول للتوظيف'],['rejected','غير مقبول'],['offer','عرض وظيفي'],['hired','تم التعيين'],['withdrawn','منسحب']];
const jobs=()=>A(state.hrRecruitmentRequisitions),candidates=()=>jobs().flatMap(j=>A(j.candidates).map(c=>({...c,jobId:j.id,jobTitle:j.title,department:j.department}))),stageName=s=>stages.find(x=>x[0]===s)?.[1]||s||'فرز أولي';
function filteredCandidates(){const f=candidateFilter;return candidates().filter(c=>(!f.job||String(c.jobId)===f.job)&&(!f.stage||c.stage===f.stage)&&(!f.day||String(c.interviewDate||'').slice(0,10)===f.day)&&(!f.q||[c.name,c.contact,c.jobTitle,c.department,c.interviewer].join(' ').toLowerCase().includes(f.q.toLowerCase()))).sort((a,b)=>(String(a.interviewDate||'9999')+' '+(a.interviewTime||'')).localeCompare(String(b.interviewDate||'9999')+' '+(b.interviewTime||''))||String(a.name).localeCompare(String(b.name),'ar'));}
function candidatesTable(){const rows=filteredCandidates();return '<div class="m16-count">'+rows.length+' مرشحًا ضمن الاختيار الحالي</div>'+table(['المرشح / التواصل','الشاغر','موعد المقابلة','المحاور / المكان','حالة المقابلة','القرار',''],rows.map(c=>'<tr><td><b>'+E(c.name)+'</b><small>'+E(c.contact||'—')+'</small></td><td>'+E(c.jobTitle)+'<small>'+E(c.department)+'</small></td><td><bdi>'+E(c.interviewDate?stamp(c.interviewDate):'لم يحدد')+'</bdi><small><bdi>'+E(c.interviewTime||'')+'</bdi></small></td><td>'+E(c.interviewer||'غير محدد')+'<small>'+E(c.interviewLocation||'')+'</small></td><td>'+E(({scheduled:'مجدولة',completed:'أُجريت',no_show:'لم يحضر',cancelled:'أُلغيت'})[c.interviewStatus]||(c.interviewDate?'مجدولة':'لم تُحدد'))+'</td><td><span class="m15-tag '+(c.stage==='accepted'||c.stage==='hired'?'m16-success':c.stage==='rejected'?'m16-danger':'')+'">'+E(stageName(c.stage))+'</span></td><td>'+btn('الموعد والنتيجة','candidate-edit',c.jobId+'|'+c.id)+'</td></tr>').join(''),'لا يوجد مرشحون مطابقون. أضف مرشحًا أو غيّر الفلتر.');}
function recruitmentHtml(){const js=jobs(),cs=candidates();return '<div class="m15" id="m15Recruitment"><div class="m15-head"><div><span class="m16-eyebrow">إدارة الفريق</span><h2>التوظيف والمقابلات</h2><p>١ إضافة مرشح · ٢ تحديد المقابلة · ٣ تسجيل النتيجة والقرار.</p></div><div class="m15-actions">'+btn('+ شاغر','job-add')+btn('+ مرشح','candidate-add','','primary')+btn('معاينة وطباعة القائمة','candidate-print')+'</div></div><div class="m15-stats">'+[['jobs','الشواغر المفتوحة',js.filter(x=>x.status!=='closed').length],['candidates','كل المرشحين',cs.length],['interview','مقابلات محددة',cs.filter(x=>x.stage==='interview').length],['accepted','مقبولون للتوظيف',cs.filter(x=>x.stage==='accepted').length]].map(([v,t,n])=>'<button type="button" data-m15="recruit" data-value="'+v+'"><span>'+t+'</span><strong>'+n+'</strong><small>عرض القائمة ←</small></button>').join('')+'</div><div class="m15-subtabs">'+btn('المرشحون والمقابلات','recruit','candidates',recruitMode==='candidates'?'active':'')+btn('الشواغر','recruit','jobs',recruitMode==='jobs'?'active':'')+'</div>'+(recruitMode==='jobs'?table(['الشاغر','القسم','المطلوب','المرشحون','الحالة',''],js.map(j=>'<tr><td><b>'+E(j.title)+'</b></td><td>'+E(j.department)+'</td><td>'+E(j.headcount||1)+'</td><td>'+btn(String(A(j.candidates).length)+' — عرض المرشحين','job-candidates',j.id)+'</td><td>'+E(j.status==='closed'?'مغلق':'مفتوح')+'</td><td><div class="m15-actions">'+btn('إضافة مرشح','candidate-add',j.id)+btn(j.status==='closed'?'إعادة فتح':'إغلاق الشاغر','job-toggle',j.id)+'</div></td></tr>').join(''),'ابدأ بإضافة شاغر وظيفي.'):'<div class="m15-toolbar m16-candidate-filters">'+input('بحث بالاسم أو التواصل','m15CandidateSearch',candidateFilter.q)+sel('الشاغر','m15CandidateJob',[['','كل الشواغر'],...js.map(j=>[j.id,j.title])],candidateFilter.job)+sel('المرحلة / القرار','m15CandidateStage',[['','كل المراحل'],...stages],candidateFilter.stage)+input('مقابلات يوم — اختياري','m16CandidateDay',candidateFilter.day,'date')+'</div><div id="m15CandidateRows">'+candidatesTable()+'</div>')+'</div>';}
window.hrProRecruitmentHtml=recruitmentHtml;
function openRecruit(mode='candidates',job=''){
 if(window.MoshPages?.pending('hr'))return openAppWith('hr',()=>openRecruit(mode,job));
if(!Q('hrApp')?.classList.contains('active'))goApp('hr');recruitMode=mode==='jobs'?'jobs':'candidates';candidateFilter={job,stage:['interview','offer','accepted','rejected'].includes(mode)?mode:'',q:'',day:''};openHRPro('recruitment');MoshHR14.dates(Q('m15Recruitment'));}
function editCandidate(arg='',jobId=''){if(!canManage()){note('إدارة المرشحين متاحة للموارد البشرية والإدارة.',true);return;}const [jId,cId]=arg.split('|'),job=jobs().find(j=>String(j.id)===String(jId||jobId)),c=A(job?.candidates).find(c=>String(c.id)===String(cId));candidateContext={jobId:job?.id||'',id:c?.id||'',created:!c};modal(c?'ملف المرشح — '+c.name:'إضافة مرشح','<div class="m16-form-section"><h3>بيانات المرشح</h3><div class="m15-grid">'+input('اسم المرشح *','m15CanName',c?.name||'')+input('الهاتف أو البريد','m15CanContact',c?.contact||'')+sel('الشاغر *','m15CanJob',[['','اختر الشاغر'],...jobs().map(j=>[j.id,j.title+' — '+j.department])],job?.id||'')+sel('المرحلة / القرار','m15CanStage',stages,c?.stage||'screening')+'</div></div><div class="m16-form-section"><h3>المقابلة</h3><div class="m15-grid">'+input('تاريخ المقابلة','m15CanInterview',c?.interviewDate||'','date')+input('الساعة','m16CanTime',c?.interviewTime||'','time')+input('اسم المحاور','m16CanInterviewer',c?.interviewer||'')+input('مكان المقابلة / رابط الاجتماع','m16CanLocation',c?.interviewLocation||'')+sel('حالة المقابلة','m16CanInterviewStatus',[['','لم تُحدد'],['scheduled','مجدولة'],['completed','أُجريت المقابلة'],['no_show','لم يحضر'],['cancelled','أُلغيت']],c?.interviewStatus||(c?.interviewDate?'scheduled':''))+input('تاريخ تسجيل القرار','m16CanDecisionDate',c?.decisionAt?String(c.decisionAt).slice(0,10):'','date')+ta('ملاحظات المقابلة وسبب القرار','m15CanNote',c?.notes||c?.note||'')+'</div><div class="m15-actions">'+btn('مقبول للتوظيف','candidate-decision','accepted')+btn('غير مقبول','candidate-decision','rejected')+'</div><p class="m15-note">الاختيار يعبّئ القرار فقط؛ اضغط حفظ لاعتماده. القبول لا ينشئ موظفًا أو عقدًا تلقائيًا، ولا يرسل موعدًا خارج التطبيق.</p></div>',btn('حفظ وإغلاق','candidate-save','','primary'));if(c)Q('m15CanJob').disabled=true;MoshHR14.dates(Q('m15Modal'));}
async function saveCandidate(){if(!canManage()||!candidateContext)return;if(!MoshHR14.dateValid(Q('m15Modal')))return;const jobId=val('m15CanJob'),job=jobs().find(j=>String(j.id)===jobId);if(!job||!val('m15CanName')){note('اسم المرشح والشاغر مطلوبان.',true);return;}const data={name:val('m15CanName'),contact:val('m15CanContact'),stage:val('m15CanStage'),notes:val('m15CanNote'),interviewDate:val('m15CanInterview'),interviewTime:val('m16CanTime'),interviewer:val('m16CanInterviewer'),interviewLocation:val('m16CanLocation'),interviewStatus:val('m16CanInterviewStatus'),decisionAt:val('m16CanDecisionDate'),updatedAt:now(),updatedBy:me()};
if(!stages.some(x=>x[0]===data.stage)){note('اختر مرحلة صحيحة.',true);return;}
if((data.stage==='interview'||data.interviewStatus==='scheduled')&&(!data.interviewDate||!data.interviewTime)){note('حدد تاريخ المقابلة وساعتها حتى يُحفظ الموعد.',true);return;}
if(data.interviewTime&&!data.interviewDate){note('حدد تاريخ المقابلة مع الساعة.',true);return;}
if(['accepted','rejected'].includes(data.stage)){if(data.stage==='accepted'&&data.interviewStatus!=='completed'){note('سجّل أن المقابلة أُجريت قبل اعتماد القبول للتوظيف.',true);return;}if(data.stage==='rejected'&&data.interviewStatus!=='completed'&&!data.notes){note('اكتب سبب عدم القبول عند عدم إجراء مقابلة.',true);return;}data.decisionAt=data.decisionAt||hrTodayIso();data.decisionBy=me();}
const ok=await transaction(()=>{const j=jobs().find(j=>String(j.id)===jobId);if(!j)throw Error('الشاغر لم يعد موجودًا');j.candidates=A(j.candidates);if(candidateContext.created)j.candidates.push({...data,id:uid('CAN'),createdAt:now(),history:[]});else{const c=j.candidates.find(c=>String(c.id)===String(candidateContext.id));if(!c)throw Error('ملف المرشح غير موجود');c.history=A(c.history);c.history.push({at:now(),by:me(),from:c.stage,to:data.stage,previousInterviewDate:c.interviewDate||'',previousInterviewTime:c.interviewTime||'',previousNotes:c.notes||''});Object.assign(c,data);}},'تم حفظ الموعد والنتيجة.');if(ok){closeModal();openRecruit('candidates',jobId);}}
function printCandidates(){const rows=filteredCandidates(),job=jobs().find(j=>String(j.id)===candidateFilter.job);const desc='الشاغر: '+(job?.title||'كل الشواغر')+' · المرحلة: '+(candidateFilter.stage?stageName(candidateFilter.stage):'كل المراحل')+(candidateFilter.day?' · المقابلات: '+stamp(candidateFilter.day):'')+' · العدد: '+rows.length;const content='<h1>قائمة المرشحين ومواعيد المقابلات</h1><p>'+E(desc)+'</p><p>تاريخ إعداد القائمة: '+E(stamp(hrTodayIso()))+' · إعداد: '+E(me())+'</p>'+table(['#','الاسم','الشاغر / القسم','التواصل','الموعد / الساعة','المحاور / المكان','حالة المقابلة','القرار'],rows.map((c,i)=>'<tr><td>'+(i+1)+'</td><td>'+E(c.name)+'</td><td>'+E(c.jobTitle)+'<br>'+E(c.department)+'</td><td>'+E(c.contact||'—')+'</td><td><bdi>'+E(c.interviewDate?stamp(c.interviewDate):'غير محدد')+'</bdi><br><bdi>'+E(c.interviewTime||'')+'</bdi></td><td>'+E(c.interviewer||'—')+'<br>'+E(c.interviewLocation||'')+'</td><td>'+E(({scheduled:'مجدولة',completed:'أُجريت',no_show:'لم يحضر',cancelled:'أُلغيت'})[c.interviewStatus]||'—')+'</td><td>'+E(stageName(c.stage))+'</td></tr>').join(''))+'<p class="m16-print-foot">MOSH GROUP · قائمة داخلية للموارد البشرية · الملاحظات الخاصة غير مدرجة.</p>';if(window.MoshV16)MoshV16.previewPrint(content);}
window.hrProAddCandidate=jobId=>editCandidate('',jobId);api.recruit={open:openRecruit,print:printCandidates};

