const oldHR=window.openHRPro;window.openHRPro=function(view='dashboard'){if(view==='dashboard')return openProductiveDistributionPage('hr');if(view==='communications')return renderComms('announcements','hr');tabState('hr','');const r=oldHR.apply(this,arguments);if(view==='recruitment'&&Q('hrProContent')&&!Q('m15Recruitment'))Q('hrProContent').innerHTML=recruitmentHtml();return r;};
const oldStaffConfig15=window.openStaffWorkflowConfig;window.openStaffWorkflowConfig=function(){tabState('hr','');return oldStaffConfig15.apply(this,arguments);};
const oldSettings=window.openSystemSettings;window.openSystemSettings=function(){const r=oldSettings.apply(this,arguments);installSettings();return r;};
function installSettings(){const host=Q('systemSettingsModal')?.querySelector('.hr-policy-settings-section');if(host&&!Q('m15ContractSettingsBtn'))host.insertAdjacentHTML('beforeend','<div class="m15 m15-note" style="margin-top:16px"><strong>قوالب عقود الموظفين</strong><p>شروط مشتركة وشروط لكل نوع عقد. تُحمّل للعقود الجديدة، وتبقى العقود المحفوظة مستقلة.</p><button type="button" id="m15ContractSettingsBtn" class="m15-btn" data-m15="templates">إعدادات شروط العقود</button></div>');}
function hrNav(){const nav=Q('hrProNav');if(!nav||Q('m15AnnouncementsNav'))return;const old=Q('hrCommunicationsTab');if(old){old.classList.add('m15-hidden');old.insertAdjacentHTML('afterend','<button type="button" id="m15AnnouncementsNav" data-m15="communications" data-value="announcements">'+icon('<path d="M3 8h4l13-5v17L7 15H3Zm4 7 2 6"/>')+'<span>تعاميم</span></button><button type="button" data-m15="communications" data-value="archive">'+icon('<rect x="4" y="5" width="16" height="4" rx="1"/><path d="M6 9v12h12V9m-8 4h4"/>')+'<span>أرشيف تنبيهات الموظفين</span></button>');}const before=nav.querySelector('[data-hr-view="reports"]');if(before)before.insertAdjacentHTML('afterend','<button type="button" data-m15="templates">'+icon('<path d="M5 3h10l4 4v14H5Zm3 6h7m-7 4h7m-7 4h4"/>')+'<span>شروط عقود الموظفين</span></button>');nav.addEventListener('click',e=>{const b=e.target.closest('button');if(b&&!b.closest('.m15-dept-tabs'))tabState('hr','');},true);}
document.addEventListener('change',e=>{const id=e.target.id;if(id==='m16CandidateDay'){if(!MoshHR14.dateValid(Q('m15Recruitment')))return;candidateFilter.day=val('m16CandidateDay');Q('m15CandidateRows').innerHTML=candidatesTable();}else if(id==='c14_type'&&Q('m15ContractClauses')){const c=contractC();if(c&&!Object.keys(c.signatures||{}).length){applyContractTemplate(true);}}else if(id==='m15TemplateScope'){templateCollect();templateScope=e.target.value;templateRender();}else if(id==='m15ArchiveEmployee'){archiveEmployee=e.target.value;Q('m15CommRows').innerHTML=archiveHtml(archiveEmployee);}else if(id==='m15CandidateJob'||id==='m15CandidateStage'){candidateFilter.job=val('m15CandidateJob');candidateFilter.stage=val('m15CandidateStage');Q('m15CandidateRows').innerHTML=candidatesTable();}});
document.addEventListener('input',e=>{if(e.target.id==='m15NoticeSearch'){commQuery=e.target.value.trim();Q('m15CommRows').innerHTML=commMode==='archive'?archiveHtml(archiveEmployee):announcementTable();}else if(e.target.id==='m15CandidateSearch'){candidateFilter.q=e.target.value.trim();Q('m15CandidateRows').innerHTML=candidatesTable();}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-m15]');if(!b)return;e.preventDefault();const a=b.dataset.m15,v=b.dataset.value||'';try{
if(a==='dept')taskTab(v,b.dataset.mode);else if(a==='sales')salesList(v);else if(a==='sales-exec')openDeptExecReportStep3('sales','المبيعات');else if(a==='modal-close')closeModal();else if(a==='templates')templates();else if(a.startsWith('clause-'))clauseAction(a,v);else if(a==='contract-apply')await applyContractTemplate();else if(a==='template-save')await templateSave();else if(a.startsWith('template-')){templateCollect();const rows=templateRows(),i=Number(v);if(a==='template-add')rows.push({id:uid('TEMPLATE'),kind:'condition',title:'',body:''});if(a==='template-remove')rows.splice(i,1);if(a==='template-up'&&i>0)[rows[i-1],rows[i]]=[rows[i],rows[i-1]];if(a==='template-down'&&i<rows.length-1)[rows[i+1],rows[i]]=[rows[i],rows[i+1]];templateRender();}
else if(a==='communications'){archiveEmployee='';commQuery='';renderComms(v,b.closest('#hrProNav')?'hr':commOwner);}else if(a==='compose')openHrNoticeComposer(v);else if(a==='notice-detail')await noticeDetail(v);else if(a==='notice-read')await noticeDetail(v,null,true);else if(a==='archive-detail'){const [pid,id]=v.split('|');if(!ownOrManager(pid)){note('السجل غير متاح لهذا الحساب.',true);return;}const r=A(getStaffProfileById(pid)?.hrNoticeArchive).find(x=>x.id===id);if(r)await noticeDetail(r.noticeId,r,!canManage()&&String(profile()?.id)===pid);}else if(a==='profile-archive')openArchive(v);else if(a==='inbox')inbox();
else if(a==='recruit')openRecruit(v);else if(a==='job-candidates')openRecruit('candidates',v);else if(a==='candidate-add')editCandidate('',v);else if(a==='candidate-edit')editCandidate(v);else if(a==='candidate-save')await saveCandidate();else if(a==='candidate-print')printCandidates();else if(a==='candidate-decision'){Q('m15CanStage').value=v;if(!val('m16CanDecisionDate'))Q('m16CanDecisionDate').value=hrTodayIso();note('تم اختيار القرار. اضغط حفظ وإغلاق لاعتماده.');}else if(a==='notice-delete')await deleteNotice(v);else if(a==='archive-delete')await deleteCopy(v);else if(a==='job-add')hrProAddRequisition();else if(a==='job-toggle'){if(!canManage())return;const j=jobs().find(j=>String(j.id)===v);if(j&&await ask(j.status==='closed'?'إعادة فتح هذا الشاغر؟':'إغلاق الشاغر مع الاحتفاظ بالمرشحين؟')){if(await transaction(()=>{j.status=j.status==='closed'?'open':'closed';j.updatedAt=now();}))openRecruit('jobs');}}
}catch(err){console.error('MOSH v15 action',a,err);note('تعذر تنفيذ الإجراء: '+err.message,true);}});
